package local.mediacenter.library
import org.junit.Test
import org.junit.Assert.*
import org.json.JSONObject
class OfflineProgressPlanTest {
 private fun server(item:String="book",episode:String?=null)=JSONObject().put("libraryItemId",item).put("episodeId",episode?:JSONObject.NULL).put("currentTime",90.0).put("isFinished",false).put("lastUpdate",123).put("hideFromContinueListening",true)
 private fun reject(block:()->Unit){try{block();fail("Accepted invalid progress")}catch(_:IllegalArgumentException){}}
 @Test fun wholeBookAndEpisodeRoutesStaySeparate(){assertEquals("api/me/progress/book",OfflineProgressPlan.path(SpokenTarget.Book("book")));assertEquals("api/me/progress/show/episode",OfflineProgressPlan.path(SpokenTarget.Episode("show","episode")));assertEquals(90.0,OfflineProgressPlan.server(server(),SpokenTarget.Book("book"),200.0).getDouble("currentTime"),0.0)}
 @Test fun episodesCannotBorrowBookOrOtherEpisodeProgress(){reject{OfflineProgressPlan.server(server("show","other"),SpokenTarget.Episode("show","episode"),200.0)};reject{OfflineProgressPlan.server(server("book","episode"),SpokenTarget.Book("book"),200.0)};reject{OfflineProgressPlan.server(server("other"),SpokenTarget.Book("book"),200.0)}}
 @Test fun missingServerProgressIsZeroOnlyAfterValidatedIdentity(){assertFalse(OfflineProgressPlan.server(null,SpokenTarget.Book("book"),200.0).getBoolean("exists"));reject{OfflineProgressPlan.server(server().apply{remove("isFinished")},SpokenTarget.Book("book"),200.0)}}
 @Test fun invalidOrOutOfTimelineValuesAreRejected(){for(v in listOf(-1.0,Double.NaN,Double.POSITIVE_INFINITY,205.0))reject{OfflineProgressPlan.position(v,200.0)};reject{OfflineProgressPlan.position(1.0,0.0)}}
 @Test fun positionWriteNeverReplaysTimeOrOverwritesUnrelatedState(){val body=OfflineProgressPlan.payload(90.0,200.0,server());assertEquals(setOf("currentTime","duration","hideFromContinueListening"),body.keys().asSequence().toSet());assertTrue(body.getBoolean("hideFromContinueListening"));assertFalse(body.has("timeListened"));assertFalse(body.has("isFinished"));assertFalse(body.has("lastUpdate"))}
 @Test fun replacingApiKeyInvalidatesPreviewEvenWhenPublicAccountNameIsUnchanged(){val target=SpokenTarget.Book("book");val account=JSONObject().put("id","one").put("url","https://fixture.invalid").put("username","").put("authMode","apiKey").put("accessToken","fictional-one");val remote=OfflineProgressPlan.server(server(),target,200.0);val first=OfflineProgressPlan.revision(account,target,"local",remote);account.put("accessToken","fictional-two");assertNotEquals(first,OfflineProgressPlan.revision(account,target,"local",remote));assertFalse(first.contains("fictional"))}
 @Test fun changedLocalServerAccountOrCompletionInvalidatesPreview(){val a=JSONObject().put("id","one").put("url","https://fixture.invalid").put("username","test");val t=SpokenTarget.Book("book");val r=OfflineProgressPlan.server(server(),t,200.0);val expected=OfflineProgressPlan.revision(a,t,"local",r);assertEquals(expected,OfflineProgressPlan.revision(a,t,"local",r));for(other in listOf(OfflineProgressPlan.revision(a,t,"changed",r),OfflineProgressPlan.revision(a,t,"local",JSONObject(r.toString()).put("lastUpdate",124)),OfflineProgressPlan.revision(a,t,"local",JSONObject(r.toString()).put("isFinished",true)),OfflineProgressPlan.revision(JSONObject(a.toString()).put("url","https://other.invalid"),t,"local",r)))reject{OfflineProgressPlan.unchanged(expected,other)}}
}
